"""HTTP entry point for SiliconRail."""

from __future__ import annotations

import argparse
import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from .rtl import RTLParseError
from .service import Service


def env_address() -> tuple[str, int]:
    raw = os.environ.get("SILICONRAIL_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid SILICONRAIL_ADDR: {raw!r}")
    return host, int(port)


_INVALID_REQUEST_MESSAGE = "body must be a JSON object with a string 'source'"


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: dict) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    _POST_ROUTES = {
        "/v1/rtl/parse": "parse_rtl",
        "/v1/rtl/widths": "analyze_widths",
    }

    def do_POST(self) -> None:
        method_name = self._POST_ROUTES.get(self.path)
        if method_name is None:
            self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})
            return
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            payload = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            self.invalid_request()
            return
        if not isinstance(payload, dict) or not isinstance(payload.get("source"), str):
            self.invalid_request()
            return
        try:
            ir = getattr(self.service, method_name)(payload["source"])
        except RTLParseError as exc:
            self.send_json(
                422,
                {
                    "error": {
                        "code": exc.code,
                        "line": exc.line,
                        "column": exc.column,
                        "message": exc.message,
                    }
                },
            )
            return
        self.send_json(200, ir)

    def invalid_request(self) -> None:
        self.send_json(
            400,
            {"error": {"code": "invalid_request", "message": _INVALID_REQUEST_MESSAGE}},
        )

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def main() -> int:
    parser = argparse.ArgumentParser(prog="siliconrail.server", description="芯片前端设计与 RTL 流程工具链")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"SiliconRail listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Verilog-2001 combinational-subset parser producing a JSON-safe circuit IR.

One source text may contain several modules. The supported subset is:

- case-sensitive identifiers (``A`` and ``a`` are distinct signals)
- decimal constants (``42``) and sized binary/hex constants
  (``4'b1010``, ``8'hFF``), underscores allowed inside digits
- line comments (``//``) and block comments (``/* */``)
- ANSI-style ``input`` / ``output`` / ``inout`` port declarations, with an
  optional ``wire`` keyword after the direction
- ``wire`` declarations and continuous ``assign`` statements
- expressions built from parentheses, bit selects, constant-range part
  selects, concatenations and the common unary/binary operators

Every parse failure raises :class:`RTLParseError` carrying a stable
machine-readable ``code`` plus a 1-based ``line``/``column``.
"""

from __future__ import annotations

import string


class RTLParseError(Exception):
    """Public parse failure.

    Attributes:
        code: machine-readable category, one of ``syntax_error``,
            ``duplicate_name``, ``undeclared_signal``, ``invalid_range`` or
            ``unsupported_construct``.
        line/column: 1-based start position of the offending construct.
        message: non-empty human-readable description.
    """

    def __init__(self, code: str, message: str, line: int, column: int) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.line = line
        self.column = column


# ---------------------------------------------------------------------------
# Lexer
# ---------------------------------------------------------------------------

_IDENT_START = set(string.ascii_letters) | {"_"}
_IDENT_CHAR = _IDENT_START | set(string.digits) | {"$"}

# Longest match first so ``<<<`` is not lexed as ``<<`` + ``<``.
_MULTI_OPS = (
    "<<<", ">>>",
    "<<", ">>", "<=", ">=", "==", "!=", "&&", "||",
    "~&", "~|", "~^", "^~", "**",
)
_SINGLE_PUNCT = set("()[]{},;:=+-*/%&|^~!<>#?")


class _Token:
    __slots__ = ("kind", "text", "line", "column", "number")

    def __init__(self, kind: str, text: str, line: int, column: int, number=None) -> None:
        self.kind = kind  # "ident" | "number" | "punct" | "eof"
        self.text = text
        self.line = line
        self.column = column
        # For number tokens: (integer value, declared width or None).
        self.number = number


def _describe(tok: _Token) -> str:
    if tok.kind == "eof":
        return "end of input"
    return repr(tok.text)


class _Lexer:
    """On-demand tokenizer.

    Tokens are produced lazily so the parser can classify a construct near
    the current position (e.g. an ``always`` block) before the lexer ever
    visits a potentially invalid character further into the source.
    """

    def __init__(self, source: str) -> None:
        self.source = source
        self.n = len(source)
        self.i = 0
        self.line = 1
        self.col = 1

    def _syntax_error(self, message: str, line: int, col: int) -> None:
        raise RTLParseError("syntax_error", message, line, col)

    def next_token(self) -> _Token:
        source, n = self.source, self.n
        while self.i < n:
            ch = source[self.i]
            if ch in " \t\r":
                self.i += 1
                self.col += 1
                continue
            if ch == "\n":
                self.i += 1
                self.line += 1
                self.col = 1
                continue
            if source.startswith("//", self.i):
                newline = source.find("\n", self.i)
                if newline == -1:
                    self.i = n
                    break
                self.i = newline  # leave the newline for position tracking
                continue
            if source.startswith("/*", self.i):
                start_line, start_col = self.line, self.col
                close = source.find("*/", self.i + 2)
                if close == -1:
                    self._syntax_error("unterminated block comment", start_line, start_col)
                segment = source[self.i:close + 2]
                last_newline = segment.rfind("\n")
                if last_newline == -1:
                    self.col += len(segment)
                else:
                    self.line += segment.count("\n")
                    self.col = len(segment) - last_newline
                self.i = close + 2
                continue
            if ch in _IDENT_START:
                start = self.i
                while self.i < n and source[self.i] in _IDENT_CHAR:
                    self.i += 1
                tok = _Token("ident", source[start:self.i], self.line, self.col)
                self.col += self.i - start
                return tok
            if ch.isdigit():
                return self._lex_number()
            for op in _MULTI_OPS:
                if source.startswith(op, self.i):
                    tok = _Token("punct", op, self.line, self.col)
                    self.i += len(op)
                    self.col += len(op)
                    return tok
            if ch in _SINGLE_PUNCT:
                tok = _Token("punct", ch, self.line, self.col)
                self.i += 1
                self.col += 1
                return tok
            self._syntax_error(f"unexpected character {ch!r}", self.line, self.col)
        return _Token("eof", "", self.line, self.col)

    def _lex_number(self) -> _Token:
        source, n = self.source, self.n
        start, line, col = self.i, self.line, self.col
        j = self.i
        while j < n and (source[j].isdigit() or source[j] == "_"):
            j += 1
        size_text = source[start:j].replace("_", "")

        if j < n and source[j] == "'":
            if j + 1 >= n or source[j + 1] not in "bBhH":
                self._syntax_error("sized literal must use base 'b' or 'h'", line, col)
            base = source[j + 1].lower()
            valid_digits = "01_" if base == "b" else "0123456789abcdefABCDEF_"
            k = j + 2
            while k < n and source[k] in valid_digits:
                k += 1
            digits = source[j + 2:k].replace("_", "")
            if not digits:
                self._syntax_error("sized literal has no digits", line, col)
            if k < n and (source[k].isalnum() or source[k] in "_$?"):
                self._syntax_error(f"invalid digit in {base!r}-based literal", line, col)
            value = int(digits, 2 if base == "b" else 16)
            self.i = k
            self.col += k - start
            return _Token("number", source[start:k], line, col, (value, int(size_text)))

        if j < n and (source[j].isalpha() or source[j] in "_$"):
            self._syntax_error("invalid decimal literal", line, col)
        self.i = j
        self.col += j - start
        return _Token("number", source[start:j], line, col, (int(size_text), None))


# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------

_DIRECTIONS = ("input", "output", "inout")
_SUPPORTED_HEADER = {"module", "endmodule", "wire", "assign"} | set(_DIRECTIONS)

# Keywords that introduce constructs deliberately outside this subset:
# procedural blocks, instances, parameters, tasks/functions and friends.
_UNSUPPORTED_KEYWORDS = {
    "always", "initial", "reg", "parameter", "localparam", "integer", "genvar",
    "function", "endfunction", "task", "endtask", "generate", "endgenerate",
    "for", "while", "repeat", "forever", "begin", "end", "if", "else",
    "case", "casex", "casez", "posedge", "negedge", "signed", "unsigned",
    "real", "realtime", "time", "tri", "wand", "wor", "supply0", "supply1",
    "defparam", "specify", "endspecify", "primitive", "endprimitive",
}

_BINARY_PREC = {
    "||": 1,
    "&&": 2,
    "|": 3,
    "^": 4, "~^": 4, "^~": 4,
    "&": 5,
    "==": 6, "!=": 6,
    "<": 7, "<=": 7, ">": 7, ">=": 7,
    "<<": 8, ">>": 8, "<<<": 8, ">>>": 8,
    "+": 9, "-": 9,
    "*": 10, "/": 10, "%": 10,
    "**": 11,
}
_RIGHT_ASSOC = {"**"}
_UNARY_OPS = {"+", "-", "~", "!", "&", "|", "^", "~&", "~|", "~^", "^~"}


class _Parser:
    def __init__(self, source: str) -> None:
        self.lexer = _Lexer(source)
        self.current = self.lexer.next_token()

    # -- token stream ------------------------------------------------------

    def peek(self) -> _Token:
        return self.current

    def advance(self) -> _Token:
        tok = self.current
        if tok.kind != "eof":
            self.current = self.lexer.next_token()
        return tok

    def raise_error(self, code: str, message: str, tok: _Token | None = None) -> None:
        tok = tok if tok is not None else self.peek()
        raise RTLParseError(code, message, tok.line, tok.column)

    def at_punct(self, text: str) -> bool:
        tok = self.peek()
        return tok.kind == "punct" and tok.text == text

    def at_ident(self, text: str) -> bool:
        tok = self.peek()
        return tok.kind == "ident" and tok.text == text

    def expect_punct(self, text: str) -> _Token:
        tok = self.peek()
        if tok.kind != "punct" or tok.text != text:
            self.raise_error("syntax_error", f"expected {text!r} but found {_describe(tok)}")
        return self.advance()

    def expect_name(self, what: str) -> _Token:
        tok = self.peek()
        if tok.kind != "ident" or tok.text in _SUPPORTED_HEADER or tok.text in _UNSUPPORTED_KEYWORDS:
            self.raise_error("syntax_error", f"expected {what} but found {_describe(tok)}")
        return self.advance()

    # -- top level ---------------------------------------------------------

    def parse_source(self) -> dict:
        modules = []
        names: set[str] = set()
        while self.peek().kind != "eof":
            modules.append(self.parse_module(names))
        if not modules:
            self.raise_error("syntax_error", "source contains no module")
        return {"modules": modules}

    def parse_module(self, names: set[str]) -> dict:
        if not self.at_ident("module"):
            self.raise_error(
                "syntax_error",
                f"expected 'module' but found {_describe(self.peek())}",
            )
        self.advance()
        name_tok = self.expect_name("module name")
        if name_tok.text in names:
            self.raise_error("duplicate_name", f"duplicate module name {name_tok.text!r}", name_tok)
        names.add(name_tok.text)
        if self.at_punct("#"):
            self.raise_error(
                "unsupported_construct",
                "parameterized module headers are not supported",
            )
        self.expect_punct("(")

        ports: list[dict] = []
        declared: set[str] = set()
        if not self.at_punct(")"):
            self.parse_port_list(ports, declared)
        self.expect_punct(")")
        self.expect_punct(";")

        nets: list[dict] = []
        assigns: list[dict] = []
        refs: list[tuple[str, _Token]] = []
        while not self.at_ident("endmodule"):
            tok = self.peek()
            if tok.kind == "eof":
                self.raise_error("syntax_error", "unexpected end of input inside module")
            if tok.kind == "ident" and tok.text == "wire":
                self.advance()
                self.parse_net_decl(nets, declared)
            elif tok.kind == "ident" and tok.text == "assign":
                self.advance()
                assigns.append(self.parse_assign(refs))
            elif tok.kind == "ident" and tok.text in _UNSUPPORTED_KEYWORDS:
                self.raise_error(
                    "unsupported_construct",
                    f"construct {tok.text!r} is not supported",
                )
            elif tok.kind == "ident":
                self.raise_error(
                    "unsupported_construct",
                    f"module item starting with {tok.text!r} is not supported "
                    "(instances and procedural blocks are outside the subset)",
                )
            elif tok.kind == "punct" and tok.text == "#":
                self.raise_error("unsupported_construct", "parameter syntax is not supported")
            else:
                self.raise_error("syntax_error", f"unexpected {_describe(tok)} inside module")
        self.advance()  # consume endmodule

        # Declarations span the whole module body, so forward references are
        # legal; resolve every referenced name after the body is parsed.
        for ref_name, ref_tok in refs:
            if ref_name not in declared:
                self.raise_error(
                    "undeclared_signal",
                    f"signal {ref_name!r} is not declared in this module",
                    ref_tok,
                )

        return {"name": name_tok.text, "ports": ports, "nets": nets, "assigns": assigns}

    # -- declarations ------------------------------------------------------

    def add_declared(self, declared: set[str], name_tok: _Token) -> None:
        if name_tok.text in declared:
            self.raise_error(
                "duplicate_name",
                f"duplicate port/net name {name_tok.text!r}",
                name_tok,
            )
        declared.add(name_tok.text)

    def parse_port_list(self, ports: list[dict], declared: set[str]) -> None:
        while True:
            tok = self.peek()
            if tok.kind == "ident" and tok.text in _DIRECTIONS:
                direction = tok.text
                self.advance()
            elif tok.kind == "ident":
                # A bare name in the header is the non-ANSI style.
                self.raise_error(
                    "unsupported_construct",
                    "non-ANSI port declarations are not supported",
                )
            else:
                self.raise_error(
                    "syntax_error",
                    f"expected port direction but found {_describe(tok)}",
                )
            # ANSI headers may say ``input wire [..] a``; wire is the only
            # net kind in the subset, anything else (reg, signed, ...) is
            # rejected as unsupported.
            if self.at_ident("wire"):
                self.advance()
            elif self.peek().kind == "ident" and self.peek().text in _UNSUPPORTED_KEYWORDS:
                self.raise_error(
                    "unsupported_construct",
                    f"port kind {self.peek().text!r} is not supported",
                )
            width = self.parse_optional_range()
            while True:
                if self.peek().kind == "ident" and self.peek().text in _UNSUPPORTED_KEYWORDS:
                    self.raise_error(
                        "unsupported_construct",
                        f"port kind {self.peek().text!r} is not supported",
                    )
                name_tok = self.expect_name("port name")
                self.add_declared(declared, name_tok)
                ports.append({"name": name_tok.text, "direction": direction, "width": width})
                if not self.at_punct(","):
                    return
                self.advance()
                if any(self.at_ident(d) for d in _DIRECTIONS):
                    break  # next direction group

    def parse_net_decl(self, nets: list[dict], declared: set[str]) -> None:
        width = self.parse_optional_range()
        while True:
            name_tok = self.expect_name("net name")
            self.add_declared(declared, name_tok)
            nets.append({"name": name_tok.text, "width": width})
            if not self.at_punct(","):
                break
            self.advance()
        self.expect_punct(";")

    def parse_optional_range(self) -> int:
        if not self.at_punct("["):
            return 1
        self.advance()
        msb = self.parse_range_endpoint()
        self.expect_punct(":")
        lsb = self.parse_range_endpoint()
        self.expect_punct("]")
        return abs(msb - lsb) + 1

    def parse_range_endpoint(self) -> int:
        tok = self.peek()
        if tok.kind != "number" or tok.number[1] is not None:
            self.raise_error(
                "invalid_range",
                "range endpoint must be a non-negative decimal constant",
            )
        self.advance()
        return tok.number[0]

    # -- statements --------------------------------------------------------

    def parse_assign(self, refs: list[tuple[str, _Token]]) -> dict:
        target = self.parse_expr(refs)
        self.expect_punct("=")
        value = self.parse_expr(refs)
        self.expect_punct(";")
        return {"target": target, "value": value}

    # -- expressions -------------------------------------------------------

    def parse_expr(self, refs: list[tuple[str, _Token]], min_prec: int = 1) -> dict:
        left = self.parse_unary(refs)
        while True:
            tok = self.peek()
            if tok.kind != "punct":
                break
            prec = _BINARY_PREC.get(tok.text)
            if prec is None or prec < min_prec:
                break
            self.advance()
            next_min = prec if tok.text in _RIGHT_ASSOC else prec + 1
            right = self.parse_expr(refs, next_min)
            left = {"kind": "binary", "op": tok.text, "left": left, "right": right}
        return left

    def parse_unary(self, refs: list[tuple[str, _Token]]) -> dict:
        tok = self.peek()
        if tok.kind == "punct" and tok.text in _UNARY_OPS:
            self.advance()
            operand = self.parse_unary(refs)
            return {"kind": "unary", "op": tok.text, "operand": operand}
        return self.parse_postfix(refs)

    def parse_postfix(self, refs: list[tuple[str, _Token]]) -> dict:
        node = self.parse_primary(refs)
        while self.at_punct("["):
            bracket = self.advance()
            first = self.parse_expr(refs)
            if self.at_punct(":"):
                self.advance()
                second = self.parse_expr(refs)
                self.expect_punct("]")
                msb = self.require_const_endpoint(first, bracket)
                lsb = self.require_const_endpoint(second, bracket)
                node = {"kind": "range_select", "base": node, "msb": msb, "lsb": lsb}
            else:
                self.expect_punct("]")
                node = {"kind": "bit_select", "base": node, "index": first}
        return node

    def require_const_endpoint(self, node: dict, at: _Token) -> int:
        if node.get("kind") != "const" or node["width"] is not None or node["value"] < 0:
            self.raise_error(
                "invalid_range",
                "range select endpoints must be non-negative decimal constants",
                at,
            )
        return node["value"]

    def parse_primary(self, refs: list[tuple[str, _Token]]) -> dict:
        tok = self.peek()
        if tok.kind == "number":
            self.advance()
            value, width = tok.number
            return {"kind": "const", "value": value, "width": width}
        if tok.kind == "ident":
            if tok.text in _SUPPORTED_HEADER or tok.text in _UNSUPPORTED_KEYWORDS:
                self.raise_error("syntax_error", f"unexpected keyword {tok.text!r} in expression")
            self.advance()
            refs.append((tok.text, tok))
            return {"kind": "ref", "name": tok.text}
        if tok.kind == "punct" and tok.text == "(":
            self.advance()
            node = self.parse_expr(refs)
            self.expect_punct(")")
            return node
        if tok.kind == "punct" and tok.text == "{":
            self.advance()
            items = [self.parse_expr(refs)]
            while self.at_punct(","):
                self.advance()
                items.append(self.parse_expr(refs))
            self.expect_punct("}")
            return {"kind": "concat", "items": items}
        self.raise_error("syntax_error", f"expected expression but found {_describe(tok)}")


def parse(source: str) -> dict:
    """Parse one Verilog source text into a JSON-serializable circuit IR."""
    return _Parser(source).parse_source()

"""Unsigned bit-width inference over the parsed circuit IR.

The pass re-parses the source with :func:`siliconrail.rtl.parse` (so all
lexical, syntactic and semantic failures surface as the same
:class:`siliconrail.rtl.RTLParseError` with unchanged ``code``/``line``/
``column``/``message``) and then annotates the resulting IR in place:

- every expression node inside an assignment target or value gains a
  ``width`` field,
- every assignment gains ``target_width``, ``value_width`` and
  ``conversion`` (one of ``exact``, ``zero_extend``, ``truncate``).

Signals are treated as unsigned, matching the current subset. The
expression tree itself is never rewritten and constant values are left
untouched; ``truncate`` only labels the conversion.
"""

from __future__ import annotations

from .rtl import parse

# Binary operators whose result is a single bit.
_BINARY_ONE_BIT = {"&&", "||", "==", "!=", "<", "<=", ">", ">="}
# Binary operators whose result takes the left operand's width.
_BINARY_LEFT_WIDTH = {"<<", ">>", "<<<", ">>>"}
# Unary operators whose result is a single bit (logical not + reductions).
_UNARY_ONE_BIT = {"!", "&", "|", "^", "~&", "~|", "~^", "^~"}


def _const_width(value: int, declared: int | None) -> int:
    if declared is not None:
        return declared
    # Unsized decimal constants: wide enough to hold the value, at least
    # 32 bits; zero is therefore 32 bits as well.
    return max(value.bit_length(), 32)


def _expr_width(node: dict, declared_widths: dict[str, int]) -> int:
    kind = node["kind"]
    if kind == "const":
        width = _const_width(node["value"], node["width"])
    elif kind == "ref":
        width = declared_widths[node["name"]]
    elif kind == "bit_select":
        _expr_width(node["base"], declared_widths)
        _expr_width(node["index"], declared_widths)
        width = 1
    elif kind == "range_select":
        _expr_width(node["base"], declared_widths)
        width = abs(node["msb"] - node["lsb"]) + 1
    elif kind == "concat":
        width = sum(_expr_width(item, declared_widths) for item in node["items"])
    elif kind == "unary":
        operand = _expr_width(node["operand"], declared_widths)
        width = 1 if node["op"] in _UNARY_ONE_BIT else operand
    elif kind == "binary":
        left = _expr_width(node["left"], declared_widths)
        right = _expr_width(node["right"], declared_widths)
        op = node["op"]
        if op in _BINARY_ONE_BIT:
            width = 1
        elif op in _BINARY_LEFT_WIDTH:
            width = left
        else:
            width = max(left, right)
    else:  # pragma: no cover - the parser only emits the kinds above
        raise AssertionError(f"unknown expression kind {kind!r}")
    node["width"] = width
    return width


def _conversion(target_width: int, value_width: int) -> str:
    if value_width < target_width:
        return "zero_extend"
    if value_width > target_width:
        return "truncate"
    return "exact"


def analyze(source: str) -> dict:
    """Parse ``source`` and annotate the IR with unsigned bit widths."""
    ir = parse(source)
    for module in ir["modules"]:
        declared_widths = {port["name"]: port["width"] for port in module["ports"]}
        declared_widths.update({net["name"]: net["width"] for net in module["nets"]})
        for assign in module["assigns"]:
            target_width = _expr_width(assign["target"], declared_widths)
            value_width = _expr_width(assign["value"], declared_widths)
            assign["target_width"] = target_width
            assign["value_width"] = value_width
            assign["conversion"] = _conversion(target_width, value_width)
    return ir

import ast
import http.client
import importlib
import json
import os
from pathlib import Path
import socket
import subprocess
import sys
import time

ROOT = Path.cwd()
SOURCE = """// two modules and declaration-order checks
module alpha(input [3:0] a, input [3:0] b, output [3:0] y);
  wire [3:0] n;
  wire [3:0] k;
  assign k = 4'hA;
  assign n = (a ^ b) & k;
  assign y = {n[2:0], 1'b0};
endmodule
/* ranges use absolute endpoint difference */
module Beta(input [0:3] q, output z);
  assign z = ~q[0];
endmodule
"""


def check(condition, message):
    if not condition:
        raise AssertionError(message)
    print("PASS:", message)


def module_name(path):
    rel = path.relative_to(ROOT).with_suffix("")
    parts = list(rel.parts)
    if parts and parts[0] == "src":
        parts.pop(0)
    if parts and parts[-1] == "__init__":
        parts.pop()
    return ".".join(parts)


def product_files():
    for base in (ROOT / "src", ROOT):
        if not base.exists():
            continue
        for path in base.rglob("*.py"):
            rel = path.relative_to(ROOT)
            if any(part in {".git", ".venv", "venv", "tests", "test", "checks", "__pycache__"} for part in rel.parts):
                continue
            yield path
        if base.name == "src":
            break


def load_service():
    src = ROOT / "src"
    if src.is_dir():
        sys.path.insert(0, str(src))
    candidates = []
    for path in product_files():
        try:
            tree = ast.parse(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, SyntaxError):
            continue
        for node in tree.body:
            if isinstance(node, ast.ClassDef) and node.name == "Service" and any(isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)) and item.name == "parse_rtl" for item in node.body):
                candidates.append(module_name(path))
    errors = []
    for name in candidates:
        try:
            mod = importlib.import_module(name)
            cls = getattr(mod, "Service")
            return cls(), mod
        except Exception as exc:
            errors.append(f"{name}: {exc}")
    raise RuntimeError("Could not import the public Service implementation: " + "; ".join(errors))


def named_list(obj, *keys):
    for key in keys:
        value = obj.get(key)
        if isinstance(value, list):
            return value
    raise AssertionError(f"missing list field among {keys}")


def names(items):
    return [item.get("name") for item in items]


def width(item):
    value = item.get("width")
    check(isinstance(value, int) and not isinstance(value, bool), f"{item.get('name')} has an integer width")
    return value


def expect_parse_error(service, source, code):
    try:
        service.parse_rtl(source)
    except Exception as exc:
        check(exc.__class__.__name__ == "RTLParseError", f"{code} uses public RTLParseError")
        check(getattr(exc, "code", None) == code, f"error code is {code}")
        check(isinstance(getattr(exc, "line", None), int) and exc.line >= 1, f"{code} line is one-based")
        check(isinstance(getattr(exc, "column", None), int) and exc.column >= 1, f"{code} column is one-based")
        check(isinstance(getattr(exc, "message", None), str) and bool(exc.message.strip()), f"{code} message is nonempty")
        return
    raise AssertionError(f"expected RTLParseError({code})")


def direct_checks(verbose=True):
    service, _ = load_service()
    if verbose:
        print("DIRECT INPUT:\n" + SOURCE)
    ir = service.parse_rtl(SOURCE)
    json.dumps(ir)
    check(ir == service.parse_rtl(SOURCE), "same source produces stable equal IR")
    check(isinstance(ir, dict), "IR is a JSON object")
    modules = named_list(ir, "modules")
    check(names(modules) == ["alpha", "Beta"], "module order and case-sensitive names are preserved")
    alpha, beta = modules
    ports = named_list(alpha, "ports")
    check(names(ports) == ["a", "b", "y"], "alpha ports retain declaration order")
    check([p.get("direction") for p in ports] == ["input", "input", "output"], "port directions are retained")
    check([width(p) for p in ports] == [4, 4, 4], "descending ranges normalize to width four")
    nets = named_list(alpha, "networks", "nets", "wires")
    check(names(nets)[:2] == ["n", "k"], "wire declarations retain source order")
    check([width(n) for n in nets[:2]] == [4, 4], "wire widths are normalized")
    assigns = named_list(alpha, "assignments", "assigns", "continuous_assignments")
    check(len(assigns) == 3, "all continuous assignments retain source order")
    beta_ports = named_list(beta, "ports")
    check(width(beta_ports[0]) == 4 and width(beta_ports[1]) == 1, "ascending and omitted ranges normalize correctly")
    try:
        service.parse_rtl(7)
    except TypeError:
        print("PASS: non-string direct input raises TypeError")
    else:
        raise AssertionError("non-string direct input must raise TypeError")
    expect_parse_error(service, "", "syntax_error")
    expect_parse_error(service, "module d(input a, input a, output y); assign y=a; endmodule", "duplicate_name")
    expect_parse_error(service, "module u(input a, output y); assign y=a & missing; endmodule", "undeclared_signal")
    expect_parse_error(service, "module r(input [-1:0] a, output y); assign y=a[0]; endmodule", "invalid_range")
    expect_parse_error(service, "module x(input a, output y); child u(.a(a)); endmodule", "unsupported_construct")
    if verbose:
        print("DIRECT RESULT:\n" + json.dumps(ir, ensure_ascii=False, indent=2))
    return ir


def request(port, method, path, body=None, content_type="application/json"):
    conn = http.client.HTTPConnection("127.0.0.1", port, timeout=5)
    headers = {"Content-Type": content_type} if body is not None else {}
    conn.request(method, path, body=body, headers=headers)
    response = conn.getresponse()
    raw = response.read()
    conn.close()
    try:
        payload = json.loads(raw.decode("utf-8"))
    except Exception:
        payload = raw.decode("utf-8", "replace")
    print(f"{method} {path} -> {response.status}\n{json.dumps(payload, ensure_ascii=False, indent=2) if not isinstance(payload, str) else payload}")
    return response.status, payload


def check_invalid_request(port, body):
    status, payload = request(port, "POST", "/v1/rtl/parse", body)
    check(status == 400, "invalid request returns HTTP 400")
    check(isinstance(payload, dict) and payload.get("error", {}).get("code") == "invalid_request", "HTTP 400 error.code is invalid_request")


def http_checks(port, expected=None):
    status, health = request(port, "GET", "/healthz")
    check(status == 200 and isinstance(health, dict), "existing health endpoint remains JSON with status 200")
    status, missing = request(port, "GET", "/not-a-route")
    check(status == 404 and isinstance(missing, dict) and isinstance(missing.get("error"), dict), "unknown GET retains structured 404")
    status, parsed = request(port, "POST", "/v1/rtl/parse", json.dumps({"source": SOURCE}).encode())
    check(status == 200, "valid RTL HTTP request returns 200")
    if expected is not None:
        check(parsed == expected, "HTTP and direct entry points return identical IR")
    check_invalid_request(port, b"[]")
    check_invalid_request(port, b"{}")
    check_invalid_request(port, b'{"source":3}')
    check_invalid_request(port, b'{"source":"\xff"}')
    status, payload = request(port, "POST", "/v1/rtl/parse", json.dumps({"source": "module broken("}).encode())
    check(status == 422, "parse failure maps to HTTP 422")
    error = payload.get("error", {}) if isinstance(payload, dict) else {}
    check(set(("code", "line", "column", "message")).issubset(error), "HTTP 422 exposes all four parse error fields")
    check(error.get("code") == "syntax_error" and isinstance(error.get("line"), int) and isinstance(error.get("column"), int) and bool(error.get("message")), "HTTP parse error preserves code, location, and message")


def configure_address(port):
    address = f"127.0.0.1:{port}"
    values = {
        "SILICONRAIL_ADDR": address,
        "HOST": "127.0.0.1", "PORT": str(port), "ADDRESS": address,
        "BIND": address, "LISTEN": address, "LISTEN_ADDR": address,
        "SERVICE_ADDR": address, "SERVER_ADDR": address,
        "RTL_ADDR": address, "RTL_SERVICE_ADDR": address,
        "RTL_SERVICE_ADDRESS": address, "VERILOG_SERVICE_ADDRESS": address,
    }
    os.environ.update(values)


def serve(port):
    configure_address(port)
    src = ROOT / "src"
    if src.is_dir():
        sys.path.insert(0, str(src))
    pyproject = ROOT / "pyproject.toml"
    if pyproject.exists():
        try:
            import tomllib
            scripts = tomllib.loads(pyproject.read_text(encoding="utf-8")).get("project", {}).get("scripts", {})
            for entry in scripts.values():
                target = entry.split("[", 1)[0]
                modname, sep, funcname = target.partition(":")
                if sep:
                    func = getattr(importlib.import_module(modname), funcname)
                    sys.argv = [modname]
                    func()
                    return
        except Exception as exc:
            print(f"console entry discovery failed: {exc}", file=sys.stderr)
    candidates = []
    for path in product_files():
        try:
            text = path.read_text(encoding="utf-8")
        except Exception:
            continue
        if "/healthz" in text and ("def main" in text or "__main__" in text):
            candidates.append(module_name(path))
    if not candidates:
        raise RuntimeError("Could not locate the repository's public server entry point")
    mod = importlib.import_module(candidates[0])
    main = getattr(mod, "main", None)
    if not callable(main):
        raise RuntimeError(f"{candidates[0]} has no callable main")
    sys.argv = [candidates[0]]
    main()


def free_port():
    sock = socket.socket()
    sock.bind(("127.0.0.1", 0))
    port = sock.getsockname()[1]
    sock.close()
    return port


def full_acceptance():
    expected = direct_checks(False)
    port = free_port()
    proc = subprocess.Popen([sys.executable, str(Path(__file__).resolve()), "serve", str(port)])
    try:
        deadline = time.time() + 12
        while time.time() < deadline:
            try:
                with socket.create_connection(("127.0.0.1", port), timeout=.25):
                    break
            except OSError:
                if proc.poll() is not None:
                    raise RuntimeError(f"server exited before readiness with code {proc.returncode}")
                time.sleep(.1)
        else:
            raise RuntimeError("server did not become ready")
        http_checks(port, expected)
    finally:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except subprocess.TimeoutExpired:
            proc.kill()
            proc.wait()
    print("ALL RTL ACCEPTANCE CHECKS PASSED")


if __name__ == "__main__":
    mode = sys.argv[1] if len(sys.argv) > 1 else "accept"
    if mode == "serve":
        serve(int(sys.argv[2]))
    elif mode == "direct":
        direct_checks(True)
    elif mode == "http":
        http_checks(int(sys.argv[2]))
    elif mode == "accept":
        full_acceptance()
    else:
        raise SystemExit(f"unknown mode: {mode}")

