def fail(message):
    raise AssertionError(message)

def module_name(path, base):
    try:
        rel = path.relative_to(base).with_suffix('')
    except ValueError:
        return None
    parts = list(rel.parts)
    if parts[-1] == '__init__':
        parts.pop()
    return '.'.join(parts) if parts else None

def python_files():
    for path in ROOT.rglob('*.py'):
        if any(part in SKIP for part in path.relative_to(ROOT).parts):
            continue
        yield path

def import_bases():
    bases = [ROOT]
    if (ROOT / 'src').is_dir():
        bases.insert(0, ROOT / 'src')
    for base in reversed(bases):
        value = str(base)
        if value not in sys.path:
            sys.path.insert(0, value)
    return bases

def load_service():
    bases = import_bases()
    candidates = []
    for path in python_files():
        try:
            tree = ast.parse(path.read_text(encoding='utf-8'))
        except (OSError, UnicodeError, SyntaxError):
            continue
        for node in tree.body:
            if isinstance(node, ast.ClassDef) and node.name == 'Service':
                methods = {item.name for item in node.body if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef))}
                if {'parse_rtl', 'analyze_widths'} <= methods:
                    for base in bases:
                        name = module_name(path, base)
                        if name:
                            candidates.append(name)
    errors = []
    for name in dict.fromkeys(candidates):
        try:
            cls = getattr(importlib.import_module(name), 'Service')
            instance = cls()
            if callable(instance.parse_rtl) and callable(instance.analyze_widths):
                return instance
        except Exception as exc:
            errors.append(f'{name}: {type(exc).__name__}: {exc}')
    fail('Could not import the product Service with parse_rtl/analyze_widths. ' + '; '.join(errors))

def assert_preserved(base, analyzed, path='$'):
    if isinstance(base, dict):
        if not isinstance(analyzed, dict):
            fail(f'{path} changed from object to {type(analyzed).__name__}')
        missing = set(base) - set(analyzed)
        extra = set(analyzed) - set(base)
        if missing:
            fail(f'{path} lost fields: {sorted(missing)}')
        if extra - ADDED:
            fail(f'{path} gained unexpected fields: {sorted(extra - ADDED)}')
        for key in base:
            if key == 'width' and base[key] is None:
                width = analyzed[key]
                if not isinstance(width, int) or isinstance(width, bool) or width < 1:
                    fail(f'{path}.width was not populated with a positive integer: {width!r}')
            else:
                assert_preserved(base[key], analyzed[key], f'{path}.{key}')
    elif isinstance(base, list):
        if not isinstance(analyzed, list) or len(base) != len(analyzed):
            fail(f'{path} changed list length or type')
        for index, (left, right) in enumerate(zip(base, analyzed)):
            assert_preserved(left, right, f'{path}[{index}]')
    elif base != analyzed:
        fail(f'{path} changed from {base!r} to {analyzed!r}')

def get_assignments(result):
    modules = result.get('modules') if isinstance(result, dict) else None
    if not isinstance(modules, list) or len(modules) != 1:
        fail('Successful result must contain exactly the submitted module under top-level modules')
    module = modules[0]
    for value in module.values():
        if isinstance(value, list) and len(value) == len(EXPECTED) and all(
            isinstance(item, dict) and 'target' in item and 'value' in item for item in value
        ):
            return value
    fail('Could not find the source-ordered continuous assignments in the module IR')

def assert_expr_widths(node, path):
    if not isinstance(node, dict):
        fail(f'{path} expression is not an object')
    width = node.get('width')
    if not isinstance(width, int) or isinstance(width, bool) or width < 1:
        fail(f'{path} has invalid or missing width: {width!r}')
    for key, value in node.items():
        if key in {'location', 'loc', 'span', 'source_location'}:
            continue
        if isinstance(value, dict):
            assert_expr_widths(value, f'{path}.{key}')
        elif isinstance(value, list):
            for index, item in enumerate(value):
                if isinstance(item, dict):
                    assert_expr_widths(item, f'{path}.{key}[{index}]')

def validate_width_result(result, base):
    if not isinstance(result, dict) or not isinstance(result.get('modules'), list):
        fail('analyze_widths must return a JSON object with top-level modules')
    json.dumps(result, sort_keys=True)
    assert_preserved(base, result)
    assignments = get_assignments(result)
    for index, (assignment, expected) in enumerate(zip(assignments, EXPECTED)):
        target_width, value_width, conversion = expected
        actual = (assignment.get('target_width'), assignment.get('value_width'), assignment.get('conversion'))
        if actual != expected:
            fail(f'assignment {index} expected {expected}, got {actual}')
        assert_expr_widths(assignment['target'], f'assignments[{index}].target')
        assert_expr_widths(assignment['value'], f'assignments[{index}].value')
        if assignment['target']['width'] != target_width:
            fail(f'assignment {index} target root width disagrees with target_width')
        if assignment['value']['width'] != value_width:
            fail(f'assignment {index} value root width disagrees with value_width')

def error_signature(exc):
    return (type(exc).__name__,) + tuple(getattr(exc, key, None) for key in ('code', 'line', 'column', 'message'))

def captured_error(call):
    try:
        call()
    except Exception as exc:
        return exc
    fail('Expected an exception, but the call succeeded')

def direct_checks(service):
    before = service.parse_rtl(SOURCE)
    analyzed = service.analyze_widths(SOURCE)
    validate_width_result(analyzed, before)
    if service.analyze_widths(SOURCE) != analyzed:
        fail('Identical analyze_widths calls returned different results')
    if service.parse_rtl(SOURCE) != before:
        fail('parse_rtl changed after width analysis')
    exc = captured_error(lambda: service.analyze_widths(None))
    if not isinstance(exc, TypeError):
        fail(f'Non-string direct input raised {type(exc).__name__}, not TypeError')
    for index, source in enumerate(BAD_SOURCES):
        old = captured_error(lambda source=source: service.parse_rtl(source))
        new = captured_error(lambda source=source: service.analyze_widths(source))
        if error_signature(old) != error_signature(new):
            fail(f'Error semantics changed for rejected source {index}: {error_signature(old)} != {error_signature(new)}')
    print('PASS direct API: width rules, conversions, determinism, JSON serialization, IR preservation, and legacy errors')
    return analyzed

def server_modules():
    bases = import_bases()
    scored = []
    for path in python_files():
        try:
            text = path.read_text(encoding='utf-8')
        except (OSError, UnicodeError):
            continue
        if '/healthz' not in text and '/v1/rtl/parse' not in text and '/v1/rtl/widths' not in text:
            continue
        score = sum(token in text for token in ('/healthz', '/v1/rtl/parse', '/v1/rtl/widths', 'HTTPServer', '__main__'))
        for base in bases:
            name = module_name(path, base)
            if name:
                scored.append((score, name))
                package = name.split('.')[0]
                if (base / package / '__main__.py').is_file():
                    scored.append((score + 1, package))
    return [name for _, name in sorted(set(scored), reverse=True)]

def port_open(port):
    try:
        with socket.create_connection(('127.0.0.1', port), timeout=0.15):
            return True
    except OSError:
        return False

def stop_process(process):
    if process.poll() is None:
        process.terminate()
        try:
            process.wait(timeout=3)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait(timeout=3)

def start_server(port):
    attempts = []
    env = os.environ.copy()
    roots = [str(ROOT), str(ROOT / 'src')]
    env['PYTHONPATH'] = os.pathsep.join(roots + ([env['PYTHONPATH']] if env.get('PYTHONPATH') else []))
    for module in server_modules():
        commands = [
            [sys.executable, '-m', module, '--host', '127.0.0.1', '--port', str(port)],
            [sys.executable, '-m', module, '--port', str(port)],
            [sys.executable, '-m', module, '127.0.0.1', str(port)]
        ]
        for command in commands:
            process = subprocess.Popen(command, cwd=ROOT, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
            deadline = time.monotonic() + 4
            while time.monotonic() < deadline and process.poll() is None and not port_open(port):
                time.sleep(0.08)
            if port_open(port):
                return process, command
            stop_process(process)
            output = process.stdout.read() if process.stdout else ''
            attempts.append(' '.join(command) + ': ' + output[-400:])
    fail('Could not start the documented product HTTP module on the requested port. ' + ' | '.join(attempts))

def request(port, method, path, body=None, content_type=None):
    connection = http.client.HTTPConnection('127.0.0.1', port, timeout=5)
    headers = {}
    if content_type:
        headers['Content-Type'] = content_type
    connection.request(method, path, body=body, headers=headers)
    response = connection.getresponse()
    payload = response.read()
    headers_out = dict(response.getheaders())
    status = response.status
    connection.close()
    try:
        decoded = json.loads(payload.decode('utf-8'))
    except Exception:
        decoded = None
    return status, headers_out, payload, decoded

def find_error_fields(value):
    if isinstance(value, dict):
        if {'code', 'line', 'column', 'message'} <= set(value):
            return value
        for child in value.values():
            found = find_error_fields(child)
            if found is not None:
                return found
    elif isinstance(value, list):
        for child in value:
            found = find_error_fields(child)
            if found is not None:
                return found
    return None

def contains_value(value, expected):
    if value == expected:
        return True
    if isinstance(value, dict):
        return any(contains_value(child, expected) for child in value.values())
    if isinstance(value, list):
        return any(contains_value(child, expected) for child in value)
    return False

def http_checks(service, direct_result):
    with socket.socket() as sock:
        sock.bind(('127.0.0.1', 0))
        port = sock.getsockname()[1]
    process, command = start_server(port)
    try:
        status, _, _, health = request(port, 'GET', '/healthz')
        if status != 200:
            fail(f'/healthz changed: HTTP {status}, body={health!r}')
        valid_body = json.dumps({'source': SOURCE, 'extra': {'allowed': True}}).encode()
        status, _, raw, decoded = request(port, 'POST', '/v1/rtl/widths', valid_body, 'application/json')
        if status != 200:
            fail(f'valid /v1/rtl/widths returned HTTP {status}: {raw!r}')
        validate_width_result(decoded, service.parse_rtl(SOURCE))
        if decoded != direct_result:
            fail('HTTP and direct width-analysis results differ')
        parse_body = json.dumps({'source': SOURCE}).encode()
        status, _, raw, decoded = request(port, 'POST', '/v1/rtl/parse', parse_body, 'application/json')
        if status != 200 or decoded != service.parse_rtl(SOURCE):
            fail(f'legacy parse endpoint changed: HTTP {status}, body={raw!r}')
        invalid_requests = [
            (b'[]', 'application/json'),
            (b'{}', 'application/json'),
            (b'{"source": 7}', 'application/json'),
            (b'{"source":', 'application/json'),
            (b'{"source":"\xff"}', 'application/json')
        ]
        for index, (body, content_type) in enumerate(invalid_requests):
            status, _, raw, decoded = request(port, 'POST', '/v1/rtl/widths', body, content_type)
            if status != 400 or not contains_value(decoded, 'invalid_request'):
                fail(f'invalid request {index} expected 400 invalid_request, got {status}: {raw!r}')
        bad = BAD_SOURCES[3]
        expected_exc = captured_error(lambda: service.analyze_widths(bad))
        status, _, raw, decoded = request(port, 'POST', '/v1/rtl/widths', json.dumps({'source': bad}).encode(), 'application/json')
        fields = find_error_fields(decoded)
        expected_fields = {key: getattr(expected_exc, key, None) for key in ('code', 'line', 'column', 'message')}
        if status != 422 or fields is None or {key: fields.get(key) for key in expected_fields} != expected_fields:
            fail(f'parse failure was not preserved by HTTP: status={status}, body={raw!r}, expected={expected_fields!r}')
        status, _, _, _ = request(port, 'GET', '/definitely-unknown')
        if status != 404:
            fail(f'unknown path expected 404, got {status}')
        print('PASS HTTP API: valid widths, extra fields, invalid requests, 422 error details, and legacy routes')
        print('SERVER COMMAND:', ' '.join(command))
    finally:
        stop_process(process)

def main():
    service = load_service()
    direct_result = direct_checks(service)
    http_checks(service, direct_result)
    print('ALL ACCEPTANCE CHECKS PASSED')

if __name__ == '__main__':
    main()

